/// <summary>
/// PricingAttribute of table <c>EcoResProductCategory</c> field Category.
/// </summary>
 [GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Product, GUPPricingAttributeSourceLevel::Line)]
 [GUPPricingAttributeFieldsDiscovery(fieldStr(EcoResProductCategory, Category))]
internal class GUPPricingAttributeEcoResProductCategoryCategory extends GUPPricingAttributeEcoResProductCategory implements GUPIPricingAttribute
{

}

Method.Source:
public str getName()
{
    return fieldPName(EcoResProductCategory, Category);
}

public Query buildPricingObjectQuery(Query _query, anytype _value, Map _qdbsMap = null)
{
    QueryBuildDataSource qbds;

    qbds = this.getQueryBuildDatasource(_query, _qdbsMap);

    List recIdList = strSplit(_value, ',');
    ListEnumerator enumerator = recIdList.getEnumerator();
    while (enumerator.moveNext())
    {
        int64 value = any2Int64(enumerator.current());
        EcoResCategory ecoResCategory = EcoResCategory::find(value);
        qbds.addRange(fieldNum(EcoResCategory, NestedSetLeft)).value(SysQuery::range(ecoResCategory.NestedSetLeft, ecoResCategory.NestedSetRight));
        qbds.addRange(fieldNum(EcoResCategory, NestedSetRight)).value(SysQuery::range(ecoResCategory.NestedSetLeft, ecoResCategory.NestedSetRight));
        qbds.addRange(fieldNum(EcoResCategory, CategoryHierarchy)).value(int642Str(ecoResCategory.CategoryHierarchy));
    }

    return _query;
}

public str getRefValue(Str _defaultValue)
{
    EcoResCategory ecoResCategory;
    str ret = "";
    boolean isFirstAttributeToAppend = true;
    Query query = new Query();
    query.addDataSource(tableNum(EcoResCategory)).addRange(fieldNum(EcoResCategory, RecId)).value(_defaultValue);
    QueryRun qr = new QueryRun(query);

    List priceAttributeValueList = strSplit(_defaultValue, ',');
    ListEnumerator enumerator = priceAttributeValueList.getEnumerator();

    QueryBuildDataSource qbds = query.addDataSource(tableNum(EcoResCategory));
    while (enumerator.moveNext())
    {
        qbds.addRange(fieldNum(EcoResCategory, RecId)).value(enumerator.current());
    }

    while (qr.next())
    {
        ecoResCategory = qr.get(tableNum(EcoResCategory), 1);
        if (!isFirstAttributeToAppend)
        {
            ret += ",";
        }
        else
        {
            isFirstAttributeToAppend = false;
        }
        ret += ecoResCategory.Name;
    }

    return ret;
}

public void lookupAllowedValues(object _formStringControl)
{
    EcoResCategoryHierarchyRole retailHierarchyRole;
    EcoResCategoryHierarchy retailHierarchy;

    select firstonly CategoryHierarchy from retailHierarchyRole
                where retailHierarchyRole.NamedCategoryHierarchyRole == EcoResCategoryNamedHierarchyRole::Retail;

    retailHierarchy = EcoResCategoryHierarchy::find(retailHierarchyRole.CategoryHierarchy);

    if (!retailHierarchy)
    {
        super(_formStringControl);
        return;
    }

    container hierarchyRoles = RetailCategoryPriceRule::allowedCategoryHierarchyRoles();

    // Let isMultiHierarchy == true, to make the categorical dropdown box visible.
    EcoResCategoryLookupParameters lookupParameters = new EcoResCategoryLookupParameters();
    lookupParameters.parmMultiRoleSelectionSet(hierarchyRoles);

    Args args = new Args();
    args.name(formStr(EcoResCategorySingleLookup));
    args.caller(_formStringControl);
    args.record(retailHierarchy);
    args.lookupField(fieldNum(EcoResCategory, RecId));
    args.parmObject(lookupParameters);
    args.lookupValue(_formStringControl.valueStr());

    FormRun formRun = classfactory.formRunClass(args);
    formRun.init();

    _formStringControl.performFormLookup(formRun);
}
